t.script:
(function(){
  var root=document.querySelector('.pgx2'); if(!root) return;
  var reveals=[].slice.call(root.querySelectorAll('[data-reveal]'));
  var counts=[].slice.call(root.querySelectorAll('[data-count]'));
  var reduce=window.matchMedia && window.matchMedia('(prefers-reduced-motion:reduce)').matches;
  function showR(el){ el.style.opacity='1'; el.style.transform='none'; el.setAttribute('data-shown','1'); }
  function runCount(el){ if(el.getAttribute('data-cdone')) return; el.setAttribute('data-cdone','1');
    var tg=parseInt(el.getAttribute('data-count'),10)||0, sf=el.getAttribute('data-suffix')||'';
    if(reduce){ el.textContent=tg+sf; return; }
    var s=null; function step(ts){ if(!s)s=ts; var p=Math.min(1,(ts-s)/1100); el.textContent=Math.round(tg*(0.5-Math.cos(Math.PI*p)/2))+sf; if(p<1) requestAnimationFrame(step); } requestAnimationFrame(step); }
  function inview(el,f){ var r=el.getBoundingClientRect(), vh=window.innerHeight||document.documentElement.clientHeight; return r.top<vh*f && r.bottom>0; }
  if(reduce){ reveals.forEach(showR); counts.forEach(runCount); return; }
  function tick(){ for(var i=0;i<reveals.length;i++){ if(!reveals[i].getAttribute('data-shown') && inview(reveals[i],0.92)) showR(reveals[i]); } for(var j=0;j<counts.length;j++){ if(!counts[j].getAttribute('data-cdone') && inview(counts[j],0.95)) runCount(counts[j]); } }
  /* Odoo's website layout scrolls #wrapwrap, not window (html/body are
     overflow:hidden) — a plain window scroll listener never fires on a
     real page, so reveals only ever appeared via the 2.8s failsafe below
     and data-count numbers never animated on scroll at all. */
  (document.getElementById('wrapwrap')||window).addEventListener('scroll',tick,{passive:true}); window.addEventListener('resize',tick,{passive:true});
  [0,90,260,600].forEach(function(t){ setTimeout(tick,t); });
  setTimeout(function(){ reveals.forEach(showR); },2800);
})();
